import { test, expect } from '@playwright/test';
import { register, generateUniqueUser } from './helpers/auth';
import { generateUniqueArticle } from './helpers/articles';
import { API_MODE } from './helpers/config';

/**
 * Draft support is a feature of the Django + HTMX fullstack implementation and
 * has no equivalent in the API-only RealWorld spec, so these tests only run in
 * fullstack mode.
 */
test.describe('Drafts', () => {
  test.skip(API_MODE, 'Fullstack-only feature: drafts are not part of the API spec');

  test.beforeEach(async ({ page }) => {
    const user = generateUniqueUser();
    await register(page, user.username, user.email, user.password);
  });

  test.afterEach(async ({ context }) => {
    await context.close();
    await new Promise(resolve => setTimeout(resolve, 500));
  });

  async function saveDraft(page, article) {
    await page.goto('/editor', { waitUntil: 'load' });
    await page.fill('input[name="title"]', article.title);
    await page.fill('input[name="description"]', article.description);
    await page.fill('textarea[name="body"]', article.body);
    await Promise.all([
      page.waitForURL(/\/article\/.+/),
      page.click('button:has-text("Save Draft")'),
    ]);
  }

  test('saving a draft keeps it off the global feed but visible to the author', async ({ page }) => {
    const article = generateUniqueArticle();

    await saveDraft(page, article);

    // Author lands on the article page and sees a Draft indicator
    await expect(page).toHaveURL(/\/article\/.+/);
    await expect(page.locator('h1')).toContainText(article.title);
    await expect(page.locator('.banner .tag-pill:has-text("Draft")')).toBeVisible();

    // Draft must not appear on the global feed
    await page.goto('/', { waitUntil: 'load' });
    await expect(page.locator(`h1:has-text("${article.title}")`)).not.toBeVisible();
  });

  test('a draft appears under My Drafts, not My Articles', async ({ page }) => {
    const article = generateUniqueArticle();

    await saveDraft(page, article);

    // Grab the current username from the navbar and open the profile
    const username = (await page.locator('nav a[href^="/profile/"]').first().textContent())?.trim();
    await page.goto(`/profile/${username}`, { waitUntil: 'load' });

    // Not under My Articles (the default tab)
    await expect(page.locator(`.article-preview h1:has-text("${article.title}")`)).not.toBeVisible();

    // But present under My Drafts
    await Promise.all([
      page.waitForURL(/\/profile\/.+\/drafts/),
      page.click('a:has-text("My Drafts")'),
    ]);
    await expect(page.locator(`.article-preview h1:has-text("${article.title}")`)).toBeVisible();
  });

  test('publishing a draft makes it visible on the global feed', async ({ page }) => {
    const article = generateUniqueArticle();

    await saveDraft(page, article);
    const slug = page.url().split('/article/')[1];

    // Edit the draft and publish it
    await page.goto(`/editor/${slug}`, { waitUntil: 'load' });
    await expect(page.locator('input[name="title"]')).not.toHaveValue('', { timeout: 10000 });
    await Promise.all([
      page.waitForURL(/\/article\/.+/),
      page.click('button:has-text("Publish Article")'),
    ]);

    // Draft indicator is gone
    await expect(page.locator('.banner .tag-pill:has-text("Draft")')).not.toBeVisible();

    // Now visible on the global feed
    await page.goto('/', { waitUntil: 'load' });
    await page.waitForSelector(`h1:has-text("${article.title}")`, { timeout: 10000 });
    await expect(page.locator(`h1:has-text("${article.title}")`).first()).toBeVisible();
  });

  test('another user cannot view someone elses draft', async ({ page, browser }) => {
    const article = generateUniqueArticle();

    await saveDraft(page, article);
    const draftUrl = page.url();

    // Second user in an isolated context
    const context2 = await browser.newContext();
    const page2 = await context2.newPage();
    const user2 = generateUniqueUser();
    await register(page2, user2.username, user2.email, user2.password);

    await page2.goto(draftUrl, { waitUntil: 'load' });

    // The draft is not viewable — no article body, a not-found message instead
    await expect(page2.locator('.article-content')).not.toBeVisible();
    await expect(page2.locator(`h1:has-text("${article.title}")`)).not.toBeVisible();

    await context2.close();
  });
});

